#!/usr/bin/env bash
# GENERATED by tools/landed_parent/lp.py: lockstep bench lpt_top (flat) vs lpt_top_lp + mutants [1, 2, 4] + region audit.
# Run on the FLEET (ot-run), never on localhost.  Exit 0 iff MUT 0 PASSES, every mutant FAILS and the audit PASSES.
#   bash tools/landed_parent/test/internal_reset/gen/lpt_top_lp_bench.sh OUTDIR        (SIM=iverilog default | verilator)
set -u
cd "${LP_ROOT:-$(git -C "$(dirname "$0")" rev-parse --show-toplevel 2>/dev/null || (cd "$(dirname "$0")/../../../../.." && pwd))}"
OUT=${1:-lp_bench_out}; mkdir -p "$OUT"; SIM=${SIM:-iverilog}; rc=0
SRCS="tools/landed_parent/test/internal_reset/top.sv tools/landed_parent/test/internal_reset/child.sv rtl/common/landed_parent/ot_pl_land.sv tools/landed_parent/test/internal_reset/gen/lpt_top_lp.sv tools/landed_parent/test/internal_reset/gen/tb_lpt_top_lp.sv"
python3 tools/landed_parent/lp.py audit tools/landed_parent/test/internal_reset/spec.json > "$OUT/audit.log" 2>&1 && echo "AUDIT PASS" || { echo "AUDIT FAIL"; rc=1; }
python3 tools/landed_parent/lp.py audit tools/landed_parent/test/internal_reset/spec.json --rtl "$OUT/unland.sv" --make-unland > "$OUT/audit_unland.log" 2>&1 \
  && { echo "AUDIT-UNLAND PASSED (should FAIL)"; rc=1; } || echo "AUDIT-UNLAND FAIL (expected)"
for m in 0 1 2 4; do
  if [ "$SIM" = verilator ]; then
    verilator --binary -j 8 -Wno-fatal --top-module tb_lpt_top_lp -GMUT=$m  $SRCS -Mdir "$OUT/obj$m" > "$OUT/build_$m.log" 2>&1 \
      && "$OUT/obj$m/Vtb_lpt_top_lp" > "$OUT/mut$m.log" 2>&1
  else
    iverilog -g2012 -o "$OUT/sim$m" -s tb_lpt_top_lp -Ptb_lpt_top_lp.MUT=$m  $SRCS > "$OUT/build_$m.log" 2>&1 \
      && vvp -n "$OUT/sim$m" > "$OUT/mut$m.log" 2>&1
  fi
  r=$(grep -o 'LP_LOCKSTEP [A-Z]*' "$OUT/mut$m.log" 2>/dev/null | head -1)
  echo "MUT $m: ${r:-NO_RESULT (see $OUT/build_$m.log)}"
  if [ $m -eq 0 ]; then [ "$r" = "LP_LOCKSTEP PASS" ] || rc=1; else [ "$r" = "LP_LOCKSTEP FAIL" ] || rc=1; fi
done
echo "BENCH_EXIT $rc"; exit $rc
